/*
 * TEMPORARY BROWSER-LOCAL MODE
 *
 * Reality world records are managed by the included reality.html implementation
 * in that browser's localStorage. No PostgreSQL queries, JWT verification,
 * database migrations, or server-side world writes are made in this mode.
 * The original PostgreSQL/JWT implementation below is retained and can be
 * re-enabled by setting REALITY_STORAGE_MODE=postgres after proper setup.
 */
async function handleBrowserLocalMode(req, res) {
  const config = getConfig();
  const url = new URL(req.url || '/', 'https://reality.local');
  const action = url.searchParams.get('action');

  if (req.method === 'OPTIONS') {
    res.statusCode = 204;
    res.setHeader('Cache-Control', 'no-store');
    res.setHeader('Allow', 'GET, POST, OPTIONS');
    return res.end();
  }

  if (req.method === 'GET' && action === 'health') {
    const modelReady = Boolean(config.modelUrl && config.modelKey && config.modelId);
    return sendJson(res, 200, {
      ok: true,
      service: 'arixai-reality-engine',
      mode: 'browser-local-storage',
      persistence: 'browser-local-only',
      checks: {
        database: 'disabled',
        auth: 'disabled-temporary-mode',
        modelGateway: modelReady ? 'configured' : 'not_configured',
        objectStorage: 'disabled-for-world-state',
        allowedOrigins: 'not_required-same-origin-proxy'
      },
      notice: 'Worlds are stored in this browser profile only. They do not sync across browsers or devices.',
      timestamp: new Date().toISOString()
    });
  }

  if (req.method === 'POST') {
    const body = await getRequestBody(req, config.maxRequestBytes);
    if (body.action === 'compile_prompt') {
      const prompt = requiredString(body.prompt, 4000, 'prompt');
      const world = body.worldSpec;
      if (!world || typeof world !== 'object' || !Array.isArray(world.entities)) {
        throw httpError(400, 'WORLD_SPEC_REQUIRED', 'A valid worldSpec with an entities array is required.');
      }
      const compiled = await compileWorldPrompt({
        prompt,
        world,
        selectedEntityId: typeof body.selectedEntityId === 'string' ? body.selectedEntityId : null
      });
      return sendJson(res, 200, {
        success: true,
        commands: compiled.commands,
        explanation: compiled.explanation,
        compiledTitle: compiled.title
      });
    }
    return sendJson(res, 410, {
      success: false,
      code: 'DATABASE_MODE_DISABLED',
      error: 'Server-side world operations are disabled in browser-local mode. Use the included local-storage frontend.'
    });
  }

  return sendJson(res, 405, {
    success: false,
    code: 'METHOD_NOT_ALLOWED',
    error: 'Browser-local mode supports GET health and POST compile_prompt.'
  });
}

